import { useState, useEffect } from 'react';
import styles from './SummaryCard.module.css';

const SummaryCard = ({ 
  totalIncome: propTotalIncome = 0, 
  totalExpenses: propTotalExpenses = 0, 
  balance: propBalance = 0, 
  currentBalance: propCurrentBalance = 0 
}) => {
  // Estado inicial
  const [financialData, setFinancialData] = useState({
    totalIncome: 0,
    totalExpenses: 0,
    balance: 0,
    currentBalance: 0
  });

  // Cargar datos del localStorage al montar el componente
  useEffect(() => {
    const savedData = JSON.parse(localStorage.getItem('financialSummary'));
    if (savedData) {
      setFinancialData(savedData);
    } else {
      // Si no hay datos guardados, usar las props con valores por defecto
      setFinancialData({
        totalIncome: propTotalIncome,
        totalExpenses: propTotalExpenses,
        balance: propBalance,
        currentBalance: propCurrentBalance
      });
    }
  }, []);

  // Sincronizar con props y guardar en localStorage cuando haya cambios
  useEffect(() => {
    // Solo actualizar si las props tienen valores definidos
    if (propTotalIncome !== undefined || 
        propTotalExpenses !== undefined || 
        propBalance !== undefined || 
        propCurrentBalance !== undefined) {
      setFinancialData(prev => ({
        ...prev,
        ...(propTotalIncome !== undefined && { totalIncome: propTotalIncome }),
        ...(propTotalExpenses !== undefined && { totalExpenses: propTotalExpenses }),
        ...(propBalance !== undefined && { balance: propBalance }),
        ...(propCurrentBalance !== undefined && { currentBalance: propCurrentBalance })
      }));
    }
  }, [propTotalIncome, propTotalExpenses, propBalance, propCurrentBalance]);

  // Guardar en localStorage cuando financialData cambie
  useEffect(() => {
    localStorage.setItem('financialSummary', JSON.stringify(financialData));
  }, [financialData]);

  return (
    <div className={styles.card}>
      <h3>Resumen Financiero</h3>
      <div className={styles.summaryItem}>
        <p>Ingresos: ${financialData.totalIncome}</p>
      </div>
      <div className={styles.summaryItem}>
        <p>Gastos: ${financialData.totalExpenses}</p>
      </div>
      <div className={styles.summaryItem}>
        <p>Balance: ${financialData.balance}</p>
      </div>
      <div className={styles.summaryItem}>
        <p>Saldo Actual: ${financialData.currentBalance}</p>
      </div>
    </div>
  );
};

export default SummaryCard;
